create type public.app_role as enum ('admin','member');
create type public.finish_type as enum ('normal','early_black','wrong_pocket','scratch_on_black','other_black_foul','legacy_unknown');
create type public.expense_category as enum ('pool','meal','delivery','transport','drinks','other');
create table public.players (id uuid primary key default gen_random_uuid(), name text not null check (char_length(trim(name)) > 0), avatar_url text, active boolean not null default true, created_at timestamptz not null default now());
create unique index players_unique_name on public.players ((lower(trim(name))));
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role public.app_role not null default 'member', player_id uuid references public.players(id) on delete set null, created_at timestamptz not null default now());
create table public.sessions (id uuid primary key default gen_random_uuid(), date date not null, name text not null, notes text, created_at timestamptz not null default now());
create table public.games (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.sessions(id) on delete cascade, player_a_id uuid not null references public.players(id), player_b_id uuid not null references public.players(id), player_a_balls smallint check(player_a_balls between 0 and 8), player_b_balls smallint check(player_b_balls between 0 and 8), finish_type public.finish_type not null, black_ball_foul_player_id uuid references public.players(id), winner_id uuid not null references public.players(id), loser_id uuid not null references public.players(id), table_balls_remaining smallint check(table_balls_remaining between 0 and 15), is_legacy_import boolean not null default false, notes text, created_at timestamptz not null default now(), check(player_a_id <> player_b_id), check(winner_id <> loser_id), check(black_ball_foul_player_id is null or black_ball_foul_player_id = player_a_id or black_ball_foul_player_id = player_b_id));
create index games_session_idx on public.games(session_id); create index games_players_idx on public.games(player_a_id, player_b_id); create index sessions_date_idx on public.sessions(date);
create table public.expenses (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.sessions(id) on delete cascade, category public.expense_category not null, description text, amount_cents integer not null check(amount_cents > 0), currency text not null default 'HKD', created_at timestamptz not null default now());
create table public.expense_participants (id uuid primary key default gen_random_uuid(), expense_id uuid not null references public.expenses(id) on delete cascade, player_id uuid not null references public.players(id), unique(expense_id, player_id));
create table public.expense_payments (id uuid primary key default gen_random_uuid(), expense_id uuid not null references public.expenses(id) on delete cascade, payer_id uuid not null references public.players(id), amount_cents integer not null check(amount_cents > 0));
alter table public.players enable row level security; alter table public.profiles enable row level security; alter table public.sessions enable row level security; alter table public.games enable row level security; alter table public.expenses enable row level security; alter table public.expense_participants enable row level security; alter table public.expense_payments enable row level security;
create function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.profiles where id = auth.uid() and role = 'admin') $$;
create policy "signed in read" on public.players for select to authenticated using (true); create policy "admin manages players" on public.players for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "signed in read" on public.sessions for select to authenticated using (true); create policy "admin manages sessions" on public.sessions for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "signed in read" on public.games for select to authenticated using (true); create policy "members add games" on public.games for insert to authenticated with check (true); create policy "admins edit games" on public.games for update to authenticated using (public.is_admin()) with check (public.is_admin()); create policy "admins delete games" on public.games for delete to authenticated using (public.is_admin());
create policy "signed in read" on public.expenses for select to authenticated using (true); create policy "members add expenses" on public.expenses for insert to authenticated with check (true); create policy "admins manage expenses" on public.expenses for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "signed in read" on public.expense_participants for select to authenticated using (true); create policy "members add participants" on public.expense_participants for insert to authenticated with check (true); create policy "admins manage participants" on public.expense_participants for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "signed in read" on public.expense_payments for select to authenticated using (true); create policy "members add payments" on public.expense_payments for insert to authenticated with check (true); create policy "admins manage payments" on public.expense_payments for all to authenticated using (public.is_admin()) with check (public.is_admin());
insert into storage.buckets (id,name,public) values ('avatars','avatars',true) on conflict do nothing;
create policy "public avatar read" on storage.objects for select using (bucket_id = 'avatars'); create policy "admin avatar write" on storage.objects for insert to authenticated with check (bucket_id = 'avatars' and public.is_admin()); create policy "admin avatar update" on storage.objects for update to authenticated using (bucket_id = 'avatars' and public.is_admin());
